import React from 'react';
import 'primeicons/primeicons.css'

export default function List() {
	const [icons, setIcons] = React.useState([]);
	const [query, setQuery] = React.useState('');

	React.useEffect(() => {
		try {
			const collected = new Set();
			Array.from(document.styleSheets).forEach((sheet) => {
				let rules;
				try {
					rules = sheet.cssRules || sheet.rules;
				} catch (_e) {
					// Skip cross-origin or restricted stylesheets
					return;
				}
				if (!rules) return;
				Array.from(rules).forEach((rule) => {
					if (!rule.selectorText) return;
					// Look for selectors like ".pi-home:before"
					const selectors = rule.selectorText.split(',');
					selectors.forEach((sel) => {
						const s = sel.trim();
						if (s.startsWith('.pi-')) {
							const withoutPsuedo = s.split(':')[0];
							// Exclude the base .pi class and known utility classes
							if (withoutPsuedo === '.pi') return;
							const className = withoutPsuedo.slice(1); // remove leading dot
							// Keep only actual icon classes: start with "pi-" and not include spaces
							if (className.startsWith('pi-') && !className.includes(' ')) {
								collected.add(className);
							}
						}
					});
				});
			});
			// Sort icons alphabetically for stable rendering
			setIcons(Array.from(collected).sort());
		} catch (_e) {
			setIcons([]);
		}
	}, []);

	const filteredIcons = React.useMemo(() => {
		const q = query.trim().toLowerCase();
		if (!q) return icons;
		return icons.filter((name) => name.toLowerCase().includes(q));
	}, [icons, query]);

	return (
		<div className='fxc gp4'>
			<div className='fxb fvc gp3 mgb15'>
				<input
					type='text'
					placeholder='Search icons...'
					value={query}
					onChange={(e) => setQuery(e.target.value)}
					className='uls-input'
				/>
				<span className='text-sm uls-badge'>{filteredIcons.length} icons</span>
			</div>

			{filteredIcons.length === 0 ? (
				<div className='text-center fg-text-muted pdy6 bdr-t'>No icons found</div>
			) : (
				<div className='uls-grid gp5 col-5 text-center bdr-t'>
					{filteredIcons.map((icon) => (
						<div key={icon} className='pdy10 pdx5 fxb column fvc gp3'>
							<i className={`uls-icons s20 pi ${icon}`}></i>
							<span className='text-sm'>{icon}</span>
						</div>
					))}
				</div>
			)}
		</div>
	);
}